 1→import {
 2→  ChangeDetectionStrategy,
 3→  Component,
 4→  computed,
 5→  input,
 6→} from "@angular/core";
 7→
 8→type StressPreset = 'off' | 'mild' | 'standard' | 'intense';
 9→
10→interface PresetConfig {
11→  vignetteMax: number;
12→  bpmLow: number;
13→  bpmHigh: number;
14→  shakeOnset: number;
15→  shakeMag: number;
16→}
17→
18→const PRESETS: Record<Exclude<StressPreset, 'off'>, PresetConfig> = {
19→  mild:     { vignetteMax: 0.25, bpmLow: 50,  bpmHigh: 80,  shakeOnset: 10, shakeMag: 1   },
20→  standard: { vignetteMax: 0.40, bpmLow: 60,  bpmHigh: 120, shakeOnset: 9,  shakeMag: 1.5 },
21→  intense:  { vignetteMax: 0.55, bpmLow: 70,  bpmHigh: 160, shakeOnset: 8,  shakeMag: 2.5 },
22→};
23→
24→@Component({
25→  selector: "tfc-stress-overlay",
26→  changeDetection: ChangeDetectionStrategy.OnPush,
27→  host: {
28→    class: "stress-overlay-host",
29→  },
30→  template: `
31→    @if (severity() > 0) {
32→      <div
33→        class="stress-overlay"
34→        [style.--stress-severity]="severity()"
35→        [style.--stress-vignette-max]="vignetteMax()"
36→        [style.--stress-pulse-duration]="pulseDuration()"
37→        [style.--stress-shake]="shakeMag()"
38→      ></div>
39→    }
40→  `,
41→})
42→export class StressOverlayComponent {
43→  readonly stress = input(0);
44→  readonly preset = input<StressPreset>("standard");
45→
46→  protected readonly severity = computed(() => {
47→    if (this.preset() === "off") return 0;
48→    const s = this.stress();
49→    if (s < 7) return 0;
50→    return Math.min((s - 7) / 3, 1);
51→  });
52→
53→  private readonly config = computed(() => {
54→    const p = this.preset();
55→    if (p === "off") return null;
56→    return PRESETS[p];
57→  });
58→
59→  protected readonly vignetteMax = computed(() => this.config()?.vignetteMax ?? 0);
60→
61→  protected readonly pulseDuration = computed(() => {
62→    const c = this.config();
63→    if (!c) return "0s";
64→    const sev = this.severity();
65→    const bpm = c.bpmLow + (c.bpmHigh - c.bpmLow) * sev;
66→    return `${(60 / bpm).toFixed(2)}s`;
67→  });
68→
