/* ── Player View — Cyber Supply-Chain Console ────────── */

@layer components {
  .player-layout {
    display: grid;
    grid-template-rows: auto auto 1fr auto;
    height: 100dvh;
    overflow: hidden;
    background: var(--color-background);
    position: relative;
    z-index: 0;
  }
  .player-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-md);
    padding: var(--spacing-sm) var(--spacing-lg);
    background: var(--glass-bg), var(--color-card);
    backdrop-filter: blur(var(--glass-blur));
    -webkit-backdrop-filter: blur(var(--glass-blur));
    border-bottom: 1px solid var(--color-primary);
    box-shadow: var(--glass-shadow), var(--glow-sm);
    position: relative;
  }
  .player-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      oklch(0% 0 0 / 8%) 2px,
      oklch(0% 0 0 / 8%) 4px
    );
    pointer-events: none;
  }
  .player-header__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-primary);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }
  .player-header > .stress-bar {
    flex: 1;
  }
  .player-header__clocks {
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
  }
  .player-footer {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-xs) var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    background: var(--color-card);
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .player-footer__group {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
  }
  .player-main {
    overflow-y: auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-lg);
    background: var(--color-background);
  }
  .player-main__columns {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
  }
  .event-tile {
    display: flex;
    align-items: flex-start;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-left: 3px solid var(--color-primary);
    border-radius: 2px;
    background: var(--color-card);
    box-shadow: var(--glow-sm);
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease;
  }
  .event-tile:hover {
    border-color: var(--color-primary);
    box-shadow: var(--glow-primary);
  }
  .event-tile__icon {
    --icon-size: 2rem;
    flex-shrink: 0;
    width: var(--icon-size);
    height: var(--icon-size);
    border-radius: 2px;
    background: var(--color-primary);
    color: var(--color-primary-foreground);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
  }
  .event-tile__body {
    flex: 1;
    min-width: 0;
  }
  .event-tile__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-foreground);
  }
  .event-tile__desc {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: var(--spacing-2xs);
  }
  .event-tile__meta {
    display: flex;
    gap: var(--spacing-xs);
    margin-top: var(--spacing-xs);
  }
  .issue-tile {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-left: 3px solid var(--color-muted);
    border-radius: 2px;
    background: var(--color-card);
    cursor: pointer;
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease;
  }
  .issue-tile:hover {
    border-color: var(--color-primary);
    box-shadow: var(--glow-sm);
  }
  .issue-tile[data-lifecycle="active"] {
    border-left-color: var(--color-destructive);
    box-shadow:
      inset 0 0 12px oklch(65% 0.25 25 / 8%),
      var(--glow-sm);
    animation: threat-pulse 1.5s ease-in-out infinite;
  }
  .issue-tile[data-lifecycle="mitigated"] {
    border-left-color: var(--color-warning);
  }
  .issue-tile[data-lifecycle="resolved"] {
    border-left-color: var(--color-success);
    opacity: 0.5;
  }
  @keyframes threat-pulse {
    0%,
    100% {
      border-left-color: var(--color-destructive);
      box-shadow:
        inset 0 0 12px oklch(65% 0.25 25 / 8%),
        var(--glow-sm);
    }
    50% {
      border-left-color: oklch(70% 0.28 25);
      box-shadow:
        inset 0 0 20px oklch(65% 0.25 25 / 15%),
        0 0 18px oklch(65% 0.25 25 / 30%);
    }
  }
  .issue-tile__body {
    flex: 1;
    min-width: 0;
  }
  .issue-tile__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-foreground);
  }
  .issue-tile__desc {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: var(--spacing-2xs);
  }
  .issue-tile__countdown {
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    font-variant-numeric: tabular-nums;
    color: var(--color-destructive);
    white-space: nowrap;
    animation: countdown-blink 1s step-end infinite;
  }
  @keyframes countdown-blink {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.4;
    }
  }
  .issue-detail {
    padding: var(--spacing-md);
    border-radius: 2px;
    background: var(--color-card);
    border: 1px solid var(--color-primary);
    box-shadow: var(--glow-sm);
  }
  .issue-detail__badges {
    display: flex;
    gap: var(--spacing-sm);
    margin-top: var(--spacing-md);
  }
  .empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xl) var(--spacing-md);
    color: var(--color-muted-foreground);
  }
  .empty-state__icon {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    color: var(--color-primary);
    opacity: 0.4;
  }
  .empty-state__text {
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  @media (prefers-reduced-motion: reduce) {
    .issue-tile[data-lifecycle="active"] {
      animation: none;
    }
    .issue-tile__countdown {
      animation: none;
    }
  }

  /* ── Board Layout ──────────────────────────────────── */

  .player-main--board {
    padding: 0;
    gap: 0;
  }

  .board-turn-banner {
    display: flex;
    align-items: baseline;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-lg);
    border-bottom: 1px solid var(--color-border);
    flex-wrap: wrap;
  }
  .board-turn-banner__turn {
    font-family: var(--font-mono);
    font-size: var(--font-size-base);
    font-weight: 700;
    color: var(--color-accent);
    letter-spacing: 0.05em;
    flex-shrink: 0;
  }
  .board-turn-banner__title {
    font-size: var(--font-size-base);
    color: var(--color-foreground);
  }
  .board-turn-banner__desc {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    color: var(--color-accent);
    line-height: 1.4;
  }
  .board-turn-banner__title::after {
    content: " — ";
  }

  .board-grid {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
  }

  /* ── Role Card ─────────────────────────────────────── */

  .role-card {
    flex: 1 1 14rem;
    max-width: 22rem;
    display: flex;
    flex-direction: column;
    padding: var(--spacing-md);
    border-radius: 2px;
    background: var(--color-card);
    border: 1px solid var(--color-border);
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease,
      opacity 200ms ease;
  }
  .role-card--intel {
    border-left: 3px solid var(--color-primary);
  }
  .role-card--active {
    border: 2px solid var(--color-success);
    background: color-mix(
      in oklch,
      var(--color-success) 10%,
      var(--color-card)
    );
  }
  .role-card--done {
    border: 1px solid var(--color-muted);
    opacity: 0.7;
  }

  .role-card__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--spacing-2xs);
  }
  .role-card__role-id {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 700;
    color: var(--color-primary);
  }
  .role-card--active .role-card__role-id {
    color: var(--color-success);
  }
  .role-card__role-label {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    font-style: italic;
    margin-bottom: var(--spacing-sm);
  }

  .role-card__intel {
    font-size: var(--font-size-sm);
    color: var(--color-foreground);
    line-height: 1.5;
    margin-bottom: var(--spacing-sm);
  }
  .role-card__intel--empty {
    color: var(--color-muted-foreground);
    font-style: italic;
  }

  /* ── Advisor Recs ──────────────────────────────────── */

  .role-card__recs {
    margin-bottom: var(--spacing-sm);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-2xs);
  }
  .role-card__recs-title {
    font-size: var(--font-size-xs);
    color: var(--color-primary);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--spacing-2xs);
  }
  .role-card__rec {
    padding: var(--spacing-xs) var(--spacing-sm);
    background: var(--color-card);
    border-radius: 2px;
    border-left: 2px solid var(--color-primary);
    font-size: var(--font-size-xs);
  }
  .role-card__rec--pending {
    border-left-style: dashed;
    border-left-color: var(--color-muted);
  }
  .role-card__rec-role {
    color: var(--color-primary);
    font-weight: 600;
  }
  .role-card__rec-selection {
    color: var(--color-muted-foreground);
  }
  .role-card__rec-pending {
    color: var(--color-muted);
    font-style: italic;
  }

  /* ── Decision Form ─────────────────────────────────── */

  .role-card__decision {
    border-top: 1px solid var(--color-success);
    padding-top: var(--spacing-sm);
    margin-top: auto;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xs);
  }
  .role-card__decision-question {
    font-size: var(--font-size-xs);
    color: var(--color-success);
    font-weight: 600;
    margin-bottom: var(--spacing-2xs);
  }
  .role-card__option {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xs) var(--spacing-sm);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--font-size-xs);
    color: var(--color-foreground);
    transition: background 150ms ease;
  }
  .role-card__option:hover {
    background: var(--color-secondary);
  }
  .role-card__option--selected {
    background: var(--color-secondary);
    border-color: var(--color-success);
  }
  .role-card__system-picker {
    width: 100%;
    margin-top: var(--spacing-2xs);
    padding: var(--spacing-2xs) var(--spacing-xs);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    background: var(--color-input);
    color: var(--color-foreground);
    font-size: var(--font-size-xs);
    font-family: var(--font-mono);
  }
  .role-card__system-picker:focus {
    outline: 2px solid var(--color-ring);
    outline-offset: 1px;
  }
  .role-card__textarea {
    width: 100%;
    min-height: calc(var(--spacing-xl) * 2);
    padding: var(--spacing-xs);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    background: var(--color-input);
    color: var(--color-foreground);
    font-size: var(--font-size-xs);
    font-family: inherit;
    resize: vertical;
  }
  .role-card__textarea:focus {
    outline: 2px solid var(--color-ring);
    outline-offset: 1px;
  }
  .role-card__actions {
    display: flex;
    justify-content: flex-end;
    margin-top: var(--spacing-xs);
  }

  .role-card__done {
    border-top: 1px solid var(--color-muted);
    padding-top: var(--spacing-xs);
    margin-top: auto;
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
  }

  /* ── Stress Overlay ──────────────────────────────────── */

  .stress-overlay-host {
    display: contents;
  }
  .stress-overlay {
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 50;
    background: radial-gradient(
      ellipse at center,
      transparent calc(100% - 100% * var(--stress-vignette-max) * var(--stress-severity)),
      oklch(0% 0 0 / calc(0.7 * var(--stress-severity))) 100%
    );
    animation:
      stress-pulse var(--stress-pulse-duration) ease-in-out infinite,
      stress-shake 0.08s linear infinite;
    animation-play-state: running;
  }

  @keyframes stress-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: calc(0.5 + 0.5 * (1 - var(--stress-severity))); }
  }

  @keyframes stress-shake {
    0%  { translate: 0 0; }
    25% { translate: var(--stress-shake) calc(-1 * var(--stress-shake)); }
    50% { translate: calc(-1 * var(--stress-shake)) var(--stress-shake); }
    75% { translate: var(--stress-shake) var(--stress-shake); }
    100% { translate: calc(-0.5 * var(--stress-shake)) calc(-0.5 * var(--stress-shake)); }
  }

  @media (prefers-reduced-motion: reduce) {
    .stress-overlay {
      animation: none;
    }
  }
}

