116→<body>
117→
118→<h1>STRESS OVERLAY — VISUAL TEST</h1>
119→
120→<div class="controls">
121→  <label>Stress:
122→    <input type="range" id="stressSlider" min="0" max="10" step="0.5" value="0">
123→  </label>
124→  <span class="value" id="stressValue" data-severity="low">0</span>
125→
126→  <label>Preset:
127→    <select id="presetSelect">
128→      <option value="off">Off</option>
129→      <option value="mild">Mild</option>
130→      <option value="standard" selected>Standard</option>
131→      <option value="intense">Intense</option>
132→    </select>
133→  </label>
134→
135→  <button class="auto-btn" id="autoBtn">Auto Ramp (0→10)</button>
136→</div>
137→
138→<div class="mock-content">
139→  <div class="mock-card">
140→    <h3>NAV — Navigator</h3>
141→    <p>AIS track anomaly detected in sector Alpha-3. Recommend altering course to verify.</p>
142→    <p style="color: var(--color-primary);">☐ Alter course to investigate<br>☐ Maintain current heading</p>
143→  </div>
144→  <div class="mock-card">
145→    <h3>OPS — Operations</h3>
146→    <p>Engine room reports minor fluctuation in propulsion control system. No immediate impact.</p>
147→    <p style="color: var(--color-primary);">☐ Run diagnostics<br>☐ Monitor and report</p>
148→  </div>
149→  <div class="mock-card">
150→    <h3>CO — Commanding Officer</h3>
151→    <p>Multiple advisory inputs received. Time-critical decision required on threat posture.</p>
152→    <p style="color: #22c55e; font-weight: 600;">Select response and submit</p>
153→  </div>
154→  <div class="mock-card">
155→    <h3>CYOP — Cyber Operations</h3>
156→    <p>Network intrusion attempt detected on combat management system. Firewall held but signatures are novel.</p>
157→    <p style="color: var(--color-primary);">☐ Isolate affected segment<br>☐ Full network lockdown</p>
158→  </div>
159→  <div class="mock-card">
160→    <h3>PWO — Weapons Officer</h3>
161→    <p>Weapons systems nominal. CIWS tracking intermittent radar contact bearing 045.</p>
162→    <p style="color: var(--color-primary);">☐ Weapons tight<br>☐ Weapons free on track</p>
163→  </div>
164→  <div class="mock-card">
165→    <h3>AAWO — Air Defence</h3>
166→    <p>CAP overhead reports no hostile air activity. Radar coverage degraded in sector Bravo.</p>
167→    <p style="color: var(--color-primary);">☐ Request additional CAP<br>☐ Accept reduced coverage</p>
168→  </div>
169→</div>
170→
171→<!-- The overlay -->
172→<div id="overlay" class="stress-overlay" style="display:none;"></div>
173→
174→<script>
175→const PRESETS = {
176→  mild:     { vignetteMax: 0.25, bpmLow: 50,  bpmHigh: 80,  shakeOnset: 10, shakeMag: 1   },
177→  standard: { vignetteMax: 0.40, bpmLow: 60,  bpmHigh: 120, shakeOnset: 9,  shakeMag: 1.5 },
178→  intense:  { vignetteMax: 0.55, bpmLow: 70,  bpmHigh: 160, shakeOnset: 8,  shakeMag: 2.5 },
179→};
180→
181→const slider = document.getElementById('stressSlider');
182→const valueEl = document.getElementById('stressValue');
183→const presetEl = document.getElementById('presetSelect');
184→const overlay = document.getElementById('overlay');
185→const autoBtn = document.getElementById('autoBtn');
186→let autoInterval = null;
187→
188→function update() {
189→  const stress = parseFloat(slider.value);
190→  const preset = presetEl.value;
191→
192→  valueEl.textContent = stress.toFixed(1);
193→  valueEl.dataset.severity = stress <= 3 ? 'low' : stress <= 6 ? 'medium' : 'high';
194→
195→  if (preset === 'off' || stress < 7) {
196→    overlay.style.display = 'none';
197→    return;
198→  }
199→
200→  const config = PRESETS[preset];
201→  const severity = Math.min((stress - 7) / 3, 1);
202→  const bpm = config.bpmLow + (config.bpmHigh - config.bpmLow) * severity;
203→  const pulseDur = (60 / bpm).toFixed(2) + 's';
204→  const shakeActive = stress >= config.shakeOnset;
205→  const shakeProgress = shakeActive ? Math.min((stress - config.shakeOnset) / (10 - config.shakeOnset), 1) : 0;
206→  const shakeMag = (config.shakeMag * shakeProgress).toFixed(1) + 'px';
207→
208→  overlay.style.display = 'block';
209→  overlay.style.setProperty('--stress-severity', severity);
210→  overlay.style.setProperty('--stress-vignette-max', config.vignetteMax);
211→  overlay.style.setProperty('--stress-pulse-duration', pulseDur);
212→  overlay.style.setProperty('--stress-shake', shakeMag);
213→}
214→
215→slider.addEventListener('input', update);
216→presetEl.addEventListener('change', update);
217→
218→autoBtn.addEventListener('click', () => {
219→  if (autoInterval) {
220→    clearInterval(autoInterval);
221→    autoInterval = null;
222→    autoBtn.removeAttribute('data-active');
223→    autoBtn.textContent = 'Auto Ramp (0→10)';
224→    return;
225→  }
226→  slider.value = 0;
227→  autoBtn.setAttribute('data-active', '');
228→  autoBtn.textContent = 'Stop';
229→  let step = 0;
230→  autoInterval = setInterval(() => {
231→    step++;
232→    slider.value = (step / 50) * 10;
233→    update();
234→    if (step >= 50) {
235→      clearInterval(autoInterval);
236→      autoInterval = null;
237→      autoBtn.removeAttribute('data-active');
238→      autoBtn.textContent = 'Auto Ramp (0→10)';
