input.old_string:
if (preset === 'off' || stress < 7) {
  overlay.style.display = 'none';
  return;
}

const config = PRESETS[preset];
const severity = Math.min((stress - 7) / 3, 1);
const bpm = config.bpmLow + (config.bpmHigh - config.bpmLow) * severity;
const pulseDur = (60 / bpm).toFixed(2) + 's';
const shakeActive = stress >= config.shakeOnset;
const shakeProgress = shakeActive ? Math.min((stress - config.shakeOnset) / (10 - config.shakeOnset), 1) : 0;
const shakeMag = (config.shakeMag * shakeProgress).toFixed(1) + 'px';

overlay.style.display = 'block';
overlay.style.setProperty('--stress-severity', severity);
overlay.style.setProperty('--stress-vignette-max', config.vignetteMax);
overlay.style.setProperty('--stress-pulse-duration', pulseDur);
overlay.style.setProperty('--stress-shake', shakeMag);

